-- LOCAL ONLY synthetic records. Never seed hosted Auth. Always rollback.
begin;
do $$
declare actor uuid:=gen_random_uuid(); editor uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); request uuid:=gen_random_uuid();
 photo uuid; payload jsonb; edit jsonb; result jsonb; initial_expiry timestamptz; initial_image text; first_home jsonb;
begin
 insert into public.profiles(id,role) values(actor,'admin'),(editor,'editora'),(outsider,'foto');
 if has_table_privilege('anon','public.tsi230_homepage','select') or has_table_privilege('authenticated','public.tsi230_portfolio_commands','select') then raise exception 'configuration exposed directly';end if;
 execute 'set local role service_role';
 payload:=jsonb_build_object('request_id',request,'title','Original','image','data:image/jpeg;base64,/9j/AAAA','season_end',now()+interval '35 days','consent_until',now()+interval '40 days','consent_reference','AUT-LOCAL-ORIGINAL','contains_minors',false,'consent_confirmed',true,'guardian_confirmed',false);
 result:=public.tsi230_portfolio_admin(actor,'publish',payload);photo:=(result->'items'->0->>'id')::uuid;
 select expires_at,image into initial_expiry,initial_image from public.tsi230_portfolio where id=photo;
 edit:=jsonb_build_object('id',photo,'request_id',gen_random_uuid(),'title','Edited title');
 result:=public.tsi230_portfolio_admin(editor,'update',edit);
 if not exists(select 1 from public.tsi230_portfolio where id=photo and title='Edited title' and image=initial_image and expires_at=initial_expiry and modified_by=editor) then raise exception 'title-only changed immutable evidence or failed';end if;
 begin perform public.tsi230_portfolio_admin(outsider,'update',edit);raise exception 'photographer edited portfolio';exception when insufficient_privilege then null;end;
 begin perform public.tsi230_portfolio_admin(editor,'update',edit||'{"title":"Conflicting retry"}');raise exception 'retry changed mutation';exception when insufficient_privilege then null;end;
 perform public.tsi230_portfolio_admin(actor,'update',jsonb_build_object('id',photo,'request_id',gen_random_uuid(),'title','Newer title'));
 perform public.tsi230_portfolio_admin(editor,'update',edit);
 if (select title from public.tsi230_portfolio where id=photo)<>'Newer title' then raise exception 'late retry reverted newer content';end if;
 edit:=payload||jsonb_build_object('id',photo,'request_id',gen_random_uuid(),'title','Replacement','image','data:image/jpeg;base64,/9j/BBBB','season_end',now()+interval '100 days','consent_until',now()+interval '100 days','contains_minors',true,'guardian_confirmed',true,'guardian_reference','TUTOR-REPLACEMENT');
 perform public.tsi230_portfolio_admin(editor,'update',edit);
 if not exists(select 1 from public.tsi230_portfolio where id=photo and image='data:image/jpeg;base64,/9j/BBBB' and expires_at=initial_expiry and contains_minors and guardian_checked_at>=created_at and consent_checked_at>=created_at) then raise exception 'replacement did not retain lifetime or guardian evidence';end if;
 begin perform public.tsi230_portfolio_admin(editor,'update',edit||jsonb_build_object('request_id',gen_random_uuid(),'guardian_confirmed',false));raise exception 'missing replacement guardian accepted';exception when invalid_parameter_value then null;end;
 begin perform public.tsi230_portfolio_admin(editor,'update',edit||jsonb_build_object('request_id',gen_random_uuid(),'consent_confirmed',false));raise exception 'missing replacement consent accepted';exception when invalid_parameter_value then null;end;
 edit:=edit||jsonb_build_object('request_id',gen_random_uuid(),'consent_until',now()+interval '2 days');perform public.tsi230_portfolio_admin(editor,'update',edit);
 if (select expires_at from public.tsi230_portfolio where id=photo)<>now()+interval '2 days' then raise exception 'shorter consent not enforced';end if;
 first_home:=jsonb_build_object('id',photo,'request_id',gen_random_uuid());
 begin perform public.tsi230_portfolio_admin(editor,'homepage',first_home);raise exception 'editor changed homepage';exception when insufficient_privilege then null;end;
 result:=public.tsi230_portfolio_admin(actor,'homepage',first_home);
 if result->>'homepage_id'<>photo::text then raise exception 'homepage state missing';end if;
 result:=public.tsi230_portfolio_read(null);
 if result->'homepage'->>'id'<>photo::text or result::text like '%TUTOR-%' or result::text like '%AUT-%' or result::text like '%/9j/%' or result::text like '%created_by%' then raise exception 'public homepage metadata invalid';end if;
 perform public.tsi230_portfolio_admin(actor,'homepage',jsonb_build_object('id',null,'request_id',gen_random_uuid()));
 perform public.tsi230_portfolio_admin(actor,'homepage',first_home);
 if public.tsi230_portfolio_read(null)->'homepage'<>'null'::jsonb then raise exception 'late homepage retry overwrote newer choice';end if;
 perform public.tsi230_portfolio_admin(actor,'homepage',jsonb_build_object('id',photo,'request_id',gen_random_uuid()));
 perform public.tsi230_portfolio_admin(actor,'revoke',jsonb_build_object('id',photo));
 if public.tsi230_portfolio_read(null)->'homepage'<>'null'::jsonb then raise exception 'revoked homepage remains public';end if;
 begin perform public.tsi230_portfolio_admin(editor,'update',edit);raise exception 'revoked update replay resurrected';exception when insufficient_privilege then null;end;
 begin perform public.tsi230_portfolio_admin(actor,'homepage',jsonb_build_object('id',photo,'request_id',gen_random_uuid()));raise exception 'revoked chosen as homepage';exception when insufficient_privilege then null;end;
 payload:=payload||jsonb_build_object('request_id',gen_random_uuid());result:=public.tsi230_portfolio_admin(actor,'publish',payload);photo:=(result->'items'->0->>'id')::uuid;
 perform public.tsi230_portfolio_admin(actor,'homepage',jsonb_build_object('id',photo,'request_id',gen_random_uuid()));
 update public.tsi230_portfolio set expires_at=now()-interval '1 second' where id=photo;
 if public.tsi230_portfolio_read(null)->'homepage'<>'null'::jsonb then raise exception 'expired homepage readable before purge';end if;
 perform public.tsi230_portfolio_purge();
 if exists(select 1 from public.tsi230_homepage where photo_id is not null) then raise exception 'purge left homepage foreign reference';end if;
 raise notice 'PASS image editing: atomic replacement, title-only, current roles, consent/minors, no TTL extension, permanent retries, homepage selection/revoke/expiry';
end $$;
rollback;
